"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1315],{8936:e=>{e.exports=JSON.parse('{"functions":[{"name":"getPartCount","desc":"Counts the BaseParts among the descendants of the given instance. Warns and\\nreturns 0 if `instance` is nil.\\n\\nExample:\\n```lua\\nSearchUtil.getPartCount(workspace.NPC) -- 5\\n```","params":[{"name":"instance","desc":"","lua_type":"Instance?"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":25,"path":"src/SearchUtil.luau"}},{"name":"getDescendantParts","desc":"Gets all parts in the given instance\\n\\nExample:\\n```lua\\nSearchUtil.getDescendantParts(game.Workspace.LightPost) -- { [1] = Light, [2] = PostMeshPart }\\n```","params":[{"name":"instance","desc":"","lua_type":"Instance"}],"returns":[{"desc":"","lua_type":"{ BasePart }"}],"function_type":"static","source":{"line":56,"path":"src/SearchUtil.luau"}},{"name":"getAncestor","desc":"Walks up from `child`, starting with `child` itself, and returns the first\\ninstance that matches `condition`. A string matches by name; a function matches\\nwhen it returns true. Returns nil if nothing matches.\\n\\nExample 1:\\n```lua\\nlocal map = SearchUtil.getAncestor(part, \\"Map\\")\\n```\\n\\nExample 2:\\n```lua\\ndetector.Touched:Connect(function(part: BasePart)\\n\\tlocal bot: Model? = SearchUtil.getAncestor(part, function(instance: Instance)\\n\\t\\treturn instance:HasTag(\\"NPC\\")\\n\\tend)\\n\\n\\tif bot ~= nil then\\n\\t\\tprint(\\"NPC bot touched the detector\\")\\n\\tend\\nend)\\n```","params":[{"name":"child","desc":"","lua_type":"Instance"},{"name":"condition","desc":"","lua_type":"string | (obj: Instance) -> boolean"}],"returns":[{"desc":"","lua_type":"Instance?"}],"function_type":"static","source":{"line":98,"path":"src/SearchUtil.luau"}},{"name":"find","desc":"Searches the children of `node` (an Instance\'s children, or a table\'s values)\\nlevel by level and returns the first match. The search continues until\\n`maxDepth` is reached, a match is found, or there is nothing left to search.\\nReturns nil when no match is found.\\n\\nBy default `maxDepth` is 1, so only the direct children of `node` are searched.\\n\\n`condition` can be:\\n- a function, called with each child; the first child it returns true for is returned;\\n- a key, checked on each child: for Instance children, the child\'s own child with\\n  that name is returned; for table children, the table that has that key is\\n  returned.\\n\\nFunction condition example:\\n```lua\\nlocal player: Player? = SearchUtil.find(game.Players, function(player: Player)\\n\\treturn player.Name == \\"Player1\\"\\nend)\\n```\\n\\nKey example:\\n```lua\\n-- The first Humanoid inside a direct child of workspace\\nlocal humanoid = SearchUtil.find(workspace, \\"Humanoid\\")\\n```\\n\\nTable example:\\n```lua\\nlocal NPCs = {\\n\\t{ Name = \\"NPC1\\", Health = 0 },\\n\\t{ Name = \\"NPC2\\", Health = 20 },\\n\\t{ Name = \\"NPC3\\", Health = 0 },\\n}\\n\\nlocal firstAliveNPC = SearchUtil.find(NPCs, function(NPC)\\n\\treturn NPC.Health > 0\\nend) -- { Name = \\"NPC2\\", Health = 20 }\\n```","params":[{"name":"node","desc":"","lua_type":"Instance | { [any]: any }"},{"name":"condition","desc":"A predicate, or a key to look for.","lua_type":"any | (obj: any) -> boolean"},{"name":"maxDepth","desc":"How many levels to search. Defaults to 1.","lua_type":"number?"},{"name":"_depth","desc":"Internal: tracks the current depth. Leave as nil.","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":175,"path":"src/SearchUtil.luau"}},{"name":"exists","desc":"Checks if the given node has children (for an Instance) or keys (for a table)\\nwith the given names. A single name can be passed as a string, or several names\\nas a table. Returns false if `children` is nil.\\n\\nInstance node example:\\n```lua\\nSearchUtil.exists(\\n\\tcharacter,\\n\\t{ \\"Head\\", \\"UpperTorso\\", \\"LeftUpperArm\\", \\"RightUpperArm\\" }\\n) -- true\\n\\nSearchUtil.exists(character, \\"Head\\") -- true\\n```\\n\\nTable node example:\\n```lua\\nlocal config = { Damage = 10, Range = 20 }\\n\\nSearchUtil.exists(config, { \\"Damage\\", \\"Range\\" }) -- true\\nSearchUtil.exists(config, \\"Cooldown\\") -- false\\n```","params":[{"name":"node","desc":"","lua_type":"Instance | { [string]: any }"},{"name":"children","desc":"","lua_type":"(string | { string })?"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":272,"path":"src/SearchUtil.luau"}},{"name":"getFirstPart","desc":"Returns the first BasePart among the direct children of the given instance.\\n\\nExample:\\n```lua\\nSearchUtil.getFirstPart(workspace.Player1) -- Head\\n```","params":[{"name":"instance","desc":"","lua_type":"Instance?"}],"returns":[{"desc":"","lua_type":"BasePart?"}],"function_type":"static","source":{"line":328,"path":"src/SearchUtil.luau"}}],"properties":[],"types":[],"name":"SearchUtil","desc":"Helpers for searching Instance trees and nested tables: counting and collecting\\nparts, walking up ancestors, depth-limited searches, and checking that named\\nchildren exist.","source":{"line":9,"path":"src/SearchUtil.luau"}}')}}]);